using Microsoft.AspNetCore.Mvc.Testing;
using Testcontainers.Qdrant;
using Xunit;
using System.Net.Http.Json;

public class KnowledgeApiIntegrationTests : IAsyncLifetime
{
    private readonly QdrantContainer _qdrantContainer = new QdrantBuilder()
        .WithImage("qdrant/qdrant:v1.11.0")
        .Build();

    private WebApplicationFactory<Program> _factory = null!;
    private HttpClient _client = null!;

    public async Task InitializeAsync()
    {
        // 1. Start real Qdrant container
        await _qdrantContainer.StartAsync();

        // 2. Configure WebApplicationFactory with containerized endpoint
        _factory = new WebApplicationFactory<Program>().WithWebHostBuilder(builder =>
        {
            builder.ConfigureServices(services =>
            {
                // Point vector store registration to container
                services.AddSingleton(new QdrantClient(new Uri(_qdrantContainer.GetConnectionString())));
            });
        });

        _client = _factory.CreateClient();
    }

    [Fact]
    public async Task SearchEndpoint_ReturnsHttp200AndMatchingChunks()
    {
        // Act: Invoke actual HTTP endpoint through entire pipeline
        var response = await _client.PostAsJsonAsync("/api/knowledge/search", new
        {
            Query = "Kubernetes autoscaling",
            TenantId = "tenant-test-1"
        });

        // Assert
        response.EnsureSuccessStatusCode();
        var results = await response.Content.ReadFromJsonAsync<List<KnowledgeItemResult>>();
        Assert.NotNull(results);
    }

    public async Task DisposeAsync()
    {
        await _qdrantContainer.DisposeAsync();
        _factory.Dispose();
    }
}
